insert into public.fafsa_scholarships (slug,name,provider,description,eligibility_summary,award_amount_cents,award_amount_note,deadline,deadline_display,demographic_tags,application_requirements,selection_criteria,min_gpa,max_family_income_cents,num_awards_per_year,requires_fafsa,requires_css_profile,url,source,status,sort_order) values ('nlgja_journalism_scholarships','NLGJA Journalism Scholarships','NLGJA: The Association of LGBTQ+ Journalists','Two named scholarships for LGBTQ+ students pursuing journalism careers: the Leroy F. Aarons Scholarship and the Kay Longcope Scholarship, the latter specifically for an LGBTQ+ student of color.','Current or incoming undergraduate or graduate students at a U.S. community college or four-year university who are committed to journalism careers and NLGJA''s mission; Kay Longcope award is for LGBTQ+ students of color.',null,'Aarons up to $5,000; Longcope up to $3,000 (check official site)',NULL,'Varies - applications typically close in spring (check official site)','{lgbtq,merit,minority,journalism}'::text[],'{"Enrolled or incoming U.S. college/university student","Planned career in journalism","Work samples and essays","Commitment to fair LGBTQ+ coverage"}'::text[],'{}'::text[],null,null,null,false,false,'https://www.nlgja.org/scholarships/','curated','published',100) on conflict (slug) do nothing;
