insert into public.fafsa_scholarships (slug,name,provider,description,eligibility_summary,award_amount_cents,award_amount_note,deadline,deadline_display,demographic_tags,application_requirements,selection_criteria,min_gpa,max_family_income_cents,num_awards_per_year,requires_fafsa,requires_css_profile,url,source,status,sort_order) values ('stamps_scholars','Stamps Scholars','Stamps Scholars / Stamps Family Charitable Foundation','A prestigious merit program awarded through partner colleges — often covering a full ride plus a multi-thousand-dollar enrichment fund for study abroad, research, and leadership. At most partner schools you are considered automatically when you apply for admission.','Academically outstanding students with strong leadership and character. Awarded by partner colleges; at most schools you are automatically considered when you apply for admission — check each partner school for specifics.',null,'Varies by partner school — often a full ride plus an $8,000–$16,000 enrichment fund.',NULL,'Varies by partner school (apply to the school)','{merit,high_achieving,leadership}'::text[],'{"Apply to a Stamps partner college","Some schools require a supplemental essay/resume — check the school"}'::text[],'{"academic excellence",leadership,character}'::text[],null,null,null,false,false,'https://www.stampsscholars.org/','curated','published',26) on conflict (slug) do nothing;
