insert into public.fafsa_scholarships (slug,name,provider,description,eligibility_summary,award_amount_cents,award_amount_note,deadline,deadline_display,demographic_tags,application_requirements,selection_criteria,min_gpa,max_family_income_cents,num_awards_per_year,requires_fafsa,requires_css_profile,url,source,status,sort_order) values ('stephen_j_brady_stop_hunger_scholarship','Stephen J. Brady Stop Hunger Scholarship','Sodexo Stop Hunger Foundation','A national scholarship from the Sodexo Stop Hunger Foundation recognizing students who lead efforts to fight hunger and food insecurity in their communities. Winners also receive a grant for their hunger-relief cause.','Students ages 5 to 25 (including high school seniors and undergraduates) who have performed unpaid volunteer service fighting hunger in the past 12 months.',null,'Up to $10,000 academic scholarship plus a $5,000 grant to the student''s hunger-relief charity',NULL,'Annual - typically November 5 (opens September 5)','{service,leadership}'::text[],'{"Unpaid hunger-relief volunteer service in the past 12 months","Letter of recommendation from the served organization","Enrolled in or accepted to accredited education for the coming year"}'::text[],'{}'::text[],null,null,null,false,false,'https://www.us.stop-hunger.org/grants/youth-scholarships','curated','published',100) on conflict (slug) do nothing;
